import { textarea, field, select, checkbox, htmlEscape } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "rtRegex", label: "Regular expression", value: "(\\w+)@(\\w+\\.\\w+)" })}${field({ id: "rtFlags", label: "Flags", value: "gi", help: "g=global, i=case-insensitive, m=multiline, s=dotAll, u=unicode" })}</div><div class="field-grid">${textarea({ id: "rtInput", label: "Test string", value: "Contact alice@example.com or bob@test.org for info", full: true })}</div><div class="field-grid">${checkbox({ id: "rtHighlight", label: "Highlight matches in preview", checked: true })}${checkbox({ id: "rtReplace", label: "Show replacement preview", checked: false })}</div><div class="field-grid" id="rtReplaceGroup" style="display:none">${field({ id: "rtReplacement", label: "Replacement", value: "[email]" })}</div>`,generate(root) {const regex = root.querySelector("#rtRegex").value;const flags = root.querySelector("#rtFlags").value.trim();const input = root.querySelector("#rtInput").value;const highlight = root.querySelector("#rtHighlight").checked;const showReplace = root.querySelector("#rtReplace").checked;const replacement = root.querySelector("#rtReplacement").value || "";if (!regex) return { output: "Enter a regular expression.", preview: "" };if (!input) return { output: "Enter a test string.", preview: "" };try {const re = new RegExp(regex, flags);const matches = [...input.matchAll(re)];const lines = [];lines.push(`Pattern: /${regex}/${flags}`);lines.push(`Matches: ${matches.length}`);lines.push("---");if (matches.length === 0) {lines.push("No matches found.");} else {matches.forEach((m, i) => {lines.push(`Match ${i + 1}: "${m[0]}" at position ${m.index}`);if (m.length > 1) {m.forEach((g, j) => { if (j > 0) lines.push(` Group ${j}: "${g || "(empty)"}"`); });}});}if (showReplace && matches.length > 0) {lines.push("");lines.push("--- Replacement preview ---");lines.push(input.replace(re, replacement));}let preview = "";if (highlight && matches.length > 0) {let hl = input;let offset = 0;for (const m of matches) {const start = m.index + offset;const end = start + m[0].length;hl = hl.slice(0, start) + `<mark style="background:#fef08a;padding:0 2px;border-radius:2px">${hl.slice(start, end)}</mark>` + hl.slice(end);offset += 35;}preview = `<div style="border:1px solid #e5e7eb;border-radius:8px;padding:14px;background:#fff;font-family:monospace;font-size:14px;line-height:1.8;word-break:break-all">${hl}</div>`;}if (matches.length === 0) {preview = (preview || "") + `<div style="margin-top:8px;padding:10px;background:#fef2f2;border:1px solid #ef4444;border-radius:6px;font-size:13px;color:#dc2626">No matches found for /${regex}/${flags}</div>`;} else {preview = (preview || "") + `<div style="margin-top:8px;font-size:12px;color:#6b7280">${matches.length} match(es) found</div>`;}return { output: lines.join("\n"), preview };} catch (e) {return { output: `Invalid regex: ${e.message}`, preview: `<div style="padding:14px;background:#fef2f2;border:1px solid #ef4444;border-radius:8px;color:#dc2626">${e.message}</div>` };}}};